import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const l=JSON.parse('{"title":"第59章 一个方向","description":"","frontmatter":{},"headers":[],"relativePath":"第59章_一个方向.md","filePath":"第59章_一个方向.md"}'),o={name:"第59章_一个方向.md"};function r(n,p,s,c,i,u){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第59章-一个方向" tabindex="-1">第59章 一个方向 <a class="header-anchor" href="#第59章-一个方向" aria-label="Permalink to &quot;第59章 一个方向&quot;">​</a></h1><p>我填志愿那回，是我这一辈子唯一一次自己做主。</p><p>说是做主，其实是我妈把那张表推给我，说你自己填，填完给我看。</p><p>她说完就回客厅看电视了。</p><p>我家那个规矩我一直懂：她让你自己填，不是因为她不管，是因为她知道自己一开口，你就不填了。</p><p>那张表上要填六个学校，每个学校后面还要勾一个&quot;是否服从调剂&quot;。</p><p>我第一栏填的是澄江。</p><p>第二栏我也填澄江。</p><p>第三栏我填了一个更远的。</p><p>填到第四栏我停了。</p><p>因为我发现我这一整张表，是在算一样东西。</p><p>我算的不是学校。</p><p>我算的是：哪个城市离那条高铁近。</p><p>她走的那条线，从我们这边出去，要在澄江转。</p><p>如果我在这边，我一年可以找一次理由，走那条线。</p><p>我不一定上车，但我要在那条线上。</p><p>我把这一层想明白的时候，笔尖在纸上戳出一个洞。</p><p>我坐在那儿，第一次被自己吓着。</p><p>因为这不是&quot;我想去哪个学校&quot;。</p><p>这是我在给一件已经不存在的事，留一个通道。</p><p>我把第四栏划掉，重新填了一个更远的城市。</p><p>我想，如果我要靠那条线活着，我这四年就废了。</p><p>沈聿那天下午在走里探头进来。</p><p>他看我桌上那张表，看了不到十秒。</p><p>他说，你填得这么慢？</p><p>我说，我在想。</p><p>他说，你想什么。</p><p>我把笔放下。</p><p>我说，你说选地方这件事，到底是在选什么。</p><p>沈聿坐在我床沿上，他说了一句让我至今还记得的话。</p><p>他说，选一个你以后能够得着的东西。</p><p>我说，什么叫能够得着。</p><p>他说，就是你毕业的时候，你在那个地方待过四年，那个地方就是你的。</p><p>他说，你要是为了一个不在那儿的人选一个地方，那四年你都在门口站着。</p><p>他说，门口不算房子。</p><p>我那天晚上把这三句话在本子上拄了一遍。</p><p>拄完我在旁边写了一行。</p><p>我写：他说得对，可是我现在手上没有一个能得着的东西。</p><p>我写：只有她那边那个时差，是我能够得着的。</p><p>沈聿自己那张表十分钟填完。</p><p>他第一栏写了一个北边的城市，跟他家完全不一个方向。</p><p>我说，你为什么选那儿。</p><p>他说，因为那儿有这个专业。</p><p>我说，没别的原因？</p><p>他说，没。</p><p>他说，你这个人问题真多。</p><p>他填表的时候没有看窗外。</p><p>他交表出来，在楼上拿了一张纸，在上面写了几个字给我看。</p><p>他写：你自己想好，你别拿别人当坐标。</p><p>我把那张纸收了。</p><p>那张纸我现在还在。</p><p>我填完，拿着表出去给我妈看。</p><p>我妈把老花镜戴上，从上看到下。</p><p>她看了很久。</p><p>她说，澄江？</p><p>我说，嗯。</p><p>她说，远不远。</p><p>我说，远。</p><p>她说，多远。</p><p>我说，坐高铁要转一次车。</p><p>我妈把表放下。</p><p>她说，那你去。</p><p>她说，你去那么远干什么。</p><p>我说，那边专业好。</p><p>我妈看着我。</p><p>她说，你跟我说的是假话。</p><p>我站在那里，一句话没有。</p><p>我妈把表拿起来，重新看了一遍。</p><p>她说，我不懂这些学校。</p><p>她说，我只问你一件事。</p><p>我说，你问。</p><p>她说，你选那个地方，是不是因为有个地方让你想绕路。</p><p>我听着这一句，站在客厅中间。</p><p>我说，是。</p><p>我说完这一句，我心想糟了。</p><p>我妈没生气。</p><p>她把那张表折起来，放在桌上。</p><p>她说，那我告诉你一件事。</p><p>她说，你想绕路的那个地方，人家现在不在这儿。</p><p>她说，你现在绕过去，你绕的是一个空房子。</p><p>她说，你要是四年都绕这个空房子，你毕业的时候，你手里就只剩这个空房子了。</p><p>她说，我不反对你去远。</p><p>她说，我要你去一个跟你自己有关的地方。</p><p>那天下午我妈做了一件我没想到的事。</p><p>她把她那张表翻过来，在背面写了三个城市的名字。</p><p>她说，这三个，我年轻时候去过。</p><p>她说，我不是说它们好。</p><p>她说，我是说你去过的地方，才会长在你身上。</p><p>我看着那三个名字。</p><p>有一个跟她那个城市，正好是反方向。</p><p>那天晚上我改了第二栏和第三栏。</p><p>我把那个反方向的城市填在第二栏。</p><p>第二天我把表交上去了。</p><p>交完我给我班主任看了一眼。</p><p>我们班主任姓周。</p><p>周老师这个人很钝，他什么都看不出来，他只教书。</p><p>他看完那张表，抬头问我一句。</p><p>他说，你这个分数，澄江可以上更好的。</p><p>我说，我想去那个专业。</p><p>他说，你研究过专业？</p><p>我说，我研究过。</p><p>他把表还给我。</p><p>他说了一句话。</p><p>他说，你这个孩子，讲话从来不看着人。</p><p>我说，啊。</p><p>他说，我说你填表的时候，一直在看窗外。</p><p>他说，你这样不对。</p><p>他说，你不管填什么，你眼睛得在这儿。</p><p>那天我回宿舍的路上，一直在想这句。</p><p>我这辈子最大的毛病，不是不说。</p><p>是我做所有决定的时候，眼睛都不在这儿。</p><p>我看的都是别处。</p><p>录取结果下来那天，是七月末。</p><p>我在家里剥豆子。</p><p>我爸拿手机进厨房，说他查了，第一志愿。</p><p>我说，哪个。</p><p>他说，就是你那个反着的。</p><p>我说，好。</p><p>我爸&quot;嗯&quot;了一声，把手机放灶台边上，出去接电话。</p><p>我妈在旁边洗碗，水声很大。</p><p>她把水关小了一点，没回头。</p><p>她说，那你走的时候，跟你奶奶说一声。</p><p>我说，好。</p><p>她说，你奶奶会问你那个姑娘。</p><p>我说，你别告诉她。</p><p>我妈把碗放进水里。</p><p>她说，我不告诉她。</p><p>她说，她也不问我。</p><p>她说，她那几年就学会了一件事，她不问。</p><p>我把最后一把豆子摘完。</p><p>那天晚上，我在新的本子的第一页，写了一个城市的名字。</p><p>写完我把它划掉了。</p><p>我在旁边重新写了一行。</p><p>我写：这一次，我自己去。</p><p>七月末的夜里，我在上线以前算了一件事。</p><p>那个城市跟她那边，时差不一样。</p><p>我算出来，我跟她说话的那个&quot;七点&quot;，要往前挪一个小时。</p><p>我给她发了一句。</p><p>我说，我以后跟你的时间要变了。</p><p>她说，变多少。</p><p>我说，一小时。</p><p>她说，那以后我半夜两点能看见你。</p><p>我说，对。</p><p>她说，那我改一下我的睡觉。</p><p>她说，反正我睡得很晚。</p><p>她说完这句，隔了一会儿，又补了一条。</p><p>她说，你看，你去一个地方，第一个想的是我们的钟点。</p><p>我打字很快。</p><p>我说，不是。</p><p>她说，那是什么。</p><p>我看着屏幕。</p><p>我说，我是第一个想，然后我改成了第二个想。</p><p>她没回。</p><p>那天夜里她最后发的是三个字。</p><p>她说，去吧你。</p>',155)])])}const m=t(o,[["render",r]]);export{l as __pageData,m as default};
